/**
 * Camera-facing icons of a constant screen size, drawn with {@link OverlayRenderer} and picked by
 * their backdrops.
 *
 * @ignore
 */
export class OverlayIcons {
    /**
     * @param {OverlayRenderer} renderer - The renderer the icons are drawn with.
     * @param {Gizmo} gizmo - The gizmo owning the shapes.
     */
    constructor(renderer: OverlayRenderer, gizmo: Gizmo);
    /**
     * @type {OverlayRenderer}
     * @private
     */
    private _renderer;
    /**
     * @type {Gizmo}
     * @private
     */
    private _gizmo;
    /**
     * The icons placed this frame, with the nodes they mark.
     *
     * @type {Pool<{ shape: Shape|null, glyph: Shape|null, node: GraphNode|null }>}
     * @private
     */
    private _placed;
    /**
     * Starts a frame.
     */
    begin(): void;
    /**
     * Adds an icon at a point, a glyph over a backdrop in the theme color that
     * {@link OverlayIcons#pick} picks.
     *
     * @param {OverlayIcon} kind - The icon.
     * @param {Vec3} position - The world position.
     * @param {GraphNode} node - The node the icon marks.
     */
    add(kind: OverlayIcon, position: Vec3, node: GraphNode): void;
    /**
     * Gets the node whose icon, placed this frame, was picked by its backdrop or glyph.
     *
     * @param {MeshInstance} [meshInstance] - The picked mesh instance.
     * @returns {GraphNode|null} The node, or null when no icon was picked.
     */
    pick(meshInstance?: MeshInstance): GraphNode | null;
}
import type { OverlayIcon } from './icon-glyphs.js';
import { Vec3 } from '../../../core/math/vec3.js';
import type { GraphNode } from '../../../scene/graph-node.js';
import type { MeshInstance } from '../../../scene/mesh-instance.js';
import type { OverlayRenderer } from './overlay-renderer.js';
import type { Gizmo } from '../gizmo.js';
